	new QuantitativeScale( { 'name': 'xScale', 'clamp': null } ); // $ExpectError
	new QuantitativeScale( { 'name': 'xScale', 'clamp': [] } ); // $ExpectError
	new QuantitativeScale( { 'name': 'xScale', 'clamp': {} } ); // $ExpectError
	new QuantitativeScale( { 'name': 'xScale', 'clamp': ( x: number ): number => x } ); // $ExpectError
